INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bcc2b146-9844-4222-b920-924ad03d7c3b', 'c3c3c3c3-3030-4000-8000-000000000003', 25, 'Dia 25 — Criatividade', 'Semana 4: Integrar', '{"pch": "No princ\u00edpio, Deus criou\u2026 Criatividade \u00e9 imagem de Deus em a\u00e7\u00e3o. Mentes claras criam.", "verse": "Gn 1,1", "lectio": "Leia Gn 1,1-5. O primeiro ato criativo.", "practice": "Crie algo hoje: um texto, um desenho, uma m\u00fasica, uma receita.", "question": "O que voc\u00ea criaria se tivesse clareza?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;